import java.io.IOException;

class StoreException extends RuntimeException {
    StoreException(String message, Throwable cause) { super(message, cause); }
}

class Repo {
    String load(int id) throws IOException {
        throw new IOException("disk not ready");     // low-level failure.
    }
}

class OrderService {
    private final Repo repo = new Repo();
    String order(int id) {
        try {
            return repo.load(id);
        } catch (IOException e) {                        // translate + add context.
            throw new StoreException("loading order " + id, e);
        }
    }
}

public class Flow {
    public static void main(String[] args) {
        try {
            new OrderService().order(42);
        } catch (StoreException e) {
            System.out.println(e.getMessage());              // loading order 42
            System.out.println(e.getCause().getMessage());   // disk not ready
        }
    }
}
```

